function observeControlPlaneClient(
  options: ObserveControlPlaneClientOptions,
): ObservedControlPlaneClient {
  const subscriptions = new Set<ControlPlaneSubscription>()

  async function observe<T>(
    operation: Promise<T>,
    requestId: RequestId | null = null,
  ): Promise<T> {
    try {
      const result = await operation
      options.monitor.connected(requestId)
      return result
    } catch (error) {
      options.monitor.failure(error, options.online())
      throw error
    }
  }

  const client: ControlPlaneClient = {
    serverUrl: options.client.serverUrl,
    restore(requestOptions) {
      return observe(options.client.restore(requestOptions))
    },
    initializeOwner(initialization, requestOptions) {
      return observe(options.client.initializeOwner(initialization, requestOptions))
    },
    login(credentials, requestOptions) {
      return observe(options.client.login(credentials, requestOptions))
    },
    changePassword(change, requestOptions) {
      return observe(options.client.changePassword(change, requestOptions))
    },
    initializationStatus(requestOptions) {
      // A missing pre-auth initialization probe is presentation state for the
      // sign-in page, never a connection-health signal for mounted features.
      return options.client.initializationStatus(requestOptions)
    },
    logout(requestOptions) {
      return observe(options.client.logout(requestOptions))
    },
    command(command, requestOptions) {
      return observe(options.client.command(command, requestOptions), command.requestId)
    },
    query(query, requestOptions) {
      return observe(options.client.query(query, requestOptions), query.requestId)
    },
    subscribe(subscriptionOptions) {
      let active = true
      let raw: ControlPlaneSubscription
      const onResetRequired = subscriptionOptions.onResetRequired
      const observedOptions: ControlPlaneSubscribeOptions = {
        ...subscriptionOptions,
        async onEvent(event) {
          options.monitor.connected()
          await subscriptionOptions.onEvent(event)
        },
        ...(onResetRequired === undefined
          ? {}
          : {
              async onResetRequired(frame) {
                options.monitor.refreshRequired('SUBSCRIPTION_RESET_REQUIRED')
                return onResetRequired(frame)
              },
            }),
        async onAuthorizationRevoked(frame) {
          options.monitor.permissionDenied('PERMISSION_REVOKED')
          await subscriptionOptions.onAuthorizationRevoked?.(frame)
          await options.onAuthorizationRevoked?.(frame)
        },
        onError(error) {
          options.monitor.failure(error, options.online())
          subscriptionOptions.onError?.(error)
        },
      }
      raw = options.client.subscribe(observedOptions)
      const subscription: ControlPlaneSubscription = {
        get cursor() { return raw.cursor },
        resume() { raw.resume() },
        reconnect() {
          options.monitor.reconnecting()
          raw.reconnect()
        },
        close() {
          if (!active) return
          active = false
          subscriptions.delete(subscription)
          raw.close()
        },
      }
      subscriptions.add(subscription)
      return subscription
    },
    close() {
      for (const subscription of [...subscriptions]) subscription.close()
      options.client.close()
    },
  }

  return Object.freeze({
    client,
    reconnectAll() {
      options.monitor.reconnecting()
      for (const subscription of subscriptions) subscription.reconnect()
    },
  })
}

function createQueryCache<
  ProductSession extends ControlPlaneAuthSession,
  ProductCommandRequest extends ControlPlaneCommandRequest,
  ProductCommandResponse extends ControlPlaneCommandResponse,
  ProductQueryRequest extends QueryRequest,
  ProductQueryResponse extends QueryResultResponse,
  ProductEventFrame extends ControlPlaneWebSocketEventFrame,
  ProductResetFrame extends ControlPlaneWebSocketResetRequiredFrame,
  ProductAuthorizationRevokedFrame extends ControlPlaneWebSocketAuthorizationRevokedFrame,
  ProductSubscription extends ControlPlaneWebSocketSubscription,
  ProductSubscriptionId extends ControlPlaneWebSocketSubscriptionId,
  ProductStartAt extends ControlPlaneWebSocketSubscribeStartAt,
  ProductEventReadCursor extends EventReadCursor,
  Client extends QueryCacheClientPort<
    ProductSession,
    ProductCommandRequest,
    ProductCommandResponse,
    ProductQueryRequest,
    ProductQueryResponse,
    ProductEventFrame,
    ProductResetFrame,
    ProductAuthorizationRevokedFrame,
    ProductSubscription,
    ProductSubscriptionId,
    ProductStartAt,
    ProductEventReadCursor
  >,
>(
  options: { readonly client: Client },
): QueryCache<Client, ProductQueryRequest, ProductQueryResponse> {
  const sourceClient = options.client
  const entries = new Map<string, QueryEntry<ProductQueryRequest, ProductQueryResponse>>()
  const subscriptions = new Set<ControlPlaneSubscription>()
  let closed = false

  function entryFor(
    query: ProductQueryRequest,
  ): QueryEntry<ProductQueryRequest, ProductQueryResponse> {
    const key = queryCacheKey(query)
    const existing = entries.get(key)
    if (existing !== undefined) return existing
    const created: QueryEntry<ProductQueryRequest, ProductQueryResponse> = {
      actor: actorIdentity(query.actor),
      key,
      query: query.query,
      scope: scopeIdentity(query.scope),
      flight: null,
      snapshot: null,
      version: 0,
    }
    entries.set(key, created)
    return created
  }

  function matches(
    entry: QueryEntry<ProductQueryRequest, ProductQueryResponse>,
    invalidation: QueryInvalidation,
  ): boolean {
    return (invalidation.actor === undefined
      || entry.actor === actorIdentity(invalidation.actor))
      && (invalidation.scope === undefined
        || entry.scope === scopeIdentity(invalidation.scope))
      && (invalidation.queries === undefined
        || invalidation.queries.some(query => query === entry.query))
  }

  function invalidate(invalidation: QueryInvalidation): void {
    for (const [key, entry] of entries) {
      if (!matches(entry, invalidation)) continue
      if (invalidation.discard === true) {
        entry.flight?.controller.abort()
        entries.delete(key)
        continue
      }
      if (entry.flight !== null) {
        if (!entry.flight.invalidated) {
          entry.version += 1
          entry.flight.invalidated = true
        }
        continue
      }
      if (entry.snapshot !== null && entry.snapshot.version === entry.version) entry.version += 1
    }
  }

  function revalidate(query: QueryRequest): void {
    const key = queryCacheKey(query)
    const entry = entries.get(key)
    entry?.flight?.controller.abort()
    entries.delete(key)
  }

  function clear(_reason: QueryInvalidationReason = 'manual'): void {
    for (const entry of entries.values()) entry.flight?.controller.abort()
    entries.clear()
  }

  async function executeFlight(
    entry: QueryEntry<ProductQueryRequest, ProductQueryResponse>,
    flight: QueryFlight<ProductQueryRequest, ProductQueryResponse>,
    initial: ProductQueryRequest,
  ) {
    let request = initial
    for (;;) {
      const response = requireCorrelation(
        await sourceClient.query(request, { signal: flight.controller.signal }),
        request,
      )
      if (flight.controller.signal.aborted) throw cancelled(request.requestId)
      if (!flight.invalidated) {
        entry.snapshot = { response, version: entry.version }
        return response
      }
      const next = flight.nextRequest
      if (next === null) return response
      flight.

function createControlPlaneClient(options: ControlPlaneClientOptions): ControlPlaneClient {
  return createNeutralControlPlaneClient({
    ...options,
    generated: generatedTransport,
  })
}

function createControlPlaneClient<
  ProductSession extends AuthSessionResponse,
  ProductCommandRequest extends CommandRequest,
  ProductCommandResponse extends CommandAcceptedResponse | CommandCompletedResponse,
  ProductQueryRequest extends QueryRequest,
  ProductQueryResponse extends QueryResultResponse,
  ProductEventFrame extends ControlPlaneWebSocketEventFrame,
  ProductResetFrame extends ControlPlaneWebSocketResetRequiredFrame,
  ProductAuthorizationRevokedFrame extends ControlPlaneWebSocketAuthorizationRevokedFrame,
  ProductSubscription extends ControlPlaneWebSocketSubscription,
  ProductSubscriptionId extends ControlPlaneWebSocketSubscriptionId,
  ProductStartAt extends ControlPlaneWebSocketSubscribeStartAt,
  ProductEventReadCursor extends EventReadCursor,
>(options: ControlPlaneClientOptions<
  ProductSession,
  ProductCommandRequest,
  ProductCommandResponse,
  ProductQueryRequest,
  ProductQueryResponse,
  ProductEventFrame,
  ProductResetFrame,
  ProductAuthorizationRevokedFrame,
  ProductSubscription,
  ProductSubscriptionId,
  ProductStartAt,
  ProductEventReadCursor
>): ControlPlaneClient<
  ProductSession,
  ProductCommandRequest,
  ProductCommandResponse,
  ProductQueryRequest,
  ProductQueryResponse,
  ProductEventFrame,
  ProductResetFrame,
  ProductAuthorizationRevokedFrame,
  ProductSubscription,
  ProductSubscriptionId,
  ProductStartAt,
  ProductEventReadCursor
> {
  const generated = options.generated
  const location = parseControlPlaneServerUrl(options.serverUrl)
  const maximumRetries = options.maxNetworkRetries ?? DEFAULT_NETWORK_RETRIES
  const reconnectDelayMillis = options.reconnectDelayMillis ?? DEFAULT_RECONNECT_DELAY_MILLIS
  const transportFetch = options.transport?.fetch
  const waitBeforeRetry = options.waitBeforeRetry ?? (async () => {})
  const subscriptions = new Set<ControlPlaneSubscription>()
  let closed = false

  function requireOpen(requestId: RequestId | null = null): void {
    if (!closed) return
    throw new ControlPlaneClientError({
      kind: 'protocol',
      code: 'CLIENT_CLOSED',
      message: 'The Control Plane client is closed.',
      requestId,
      retryable: false,
    })
  }

  function reportAccessFailure(error: ControlPlaneClientError): void {
    if (error.kind !== 'authentication' && error.kind !== 'authorization') return
    try {
      options.onAccessFailure?.(error)
    } catch {
      // Authentication UI failures must not replace the canonical server error.
    }
  }

  function throwNormalized(error: unknown, requestId: RequestId | null): never {
    const normalized = normalizeError(generated, error, requestId)
    reportAccessFailure(normalized)
    throw normalized
  }

  function transportRequest(
    input: string,
    init: Omit<ControlPlaneTransportRequestInit, 'credentials' | 'signal'>,
    signal: AbortSignal | undefined,
  ): Promise<ControlPlaneHttpResponse> {
    if (transportFetch === undefined) {
      throw generated.createError({
        code: 'TRANSPORT_UNAVAILABLE',
        message: 'The browser HTTP transport is unavailable.',
        requestId: null,
        retryable: false,
        details: {},
      })
    }
    return transportFetch(input, {
      ...init,
      credentials: 'include',
      ...(signal === undefined ? {} : { signal }),
    })
  }

  async function authSessionRequest(
    method: 'DELETE' | 'GET' | 'POST',
    submission: (ControlPlanePasswordCredentials & {
      readonly bootstrapProof?: string
    }) | null,
    requestOptions: ControlPlaneRequestOptions | undefined,
  ): Promise<ProductSession | null> {
    requireOpen()
    if (signalIsAborted(requestOptions?.signal)) throw cancelledError(null)
    if (
      submission?.bootstrapProof !== undefined
      && (
        submission.bootstrapProof.length === 0
        || submission.bootstrapProof.length > 4096
        || /\s/u.test(submission.bootstrapProof)
      )
    ) {
      throw new ControlPlaneClientError({
        kind: 'authentication',
        code: 'BOOTSTRAP_PROOF_INVALID',
        message: 'Enter a valid bootstrap proof.',
        reques

generatedTransport = Object.freeze<ControlPlaneGeneratedTransport<
  AuthSessionResponse,
  CommandRequest,
  CommandAcceptedResponse | CommandCompletedResponse,
  QueryRequest,
  QueryResultResponse,
  ControlPlaneWebSocketEventFrame,
  ControlPlaneWebSocketResetRequiredFrame,
  ControlPlaneWebSocketAuthorizationRevokedFrame,
  ControlPlaneWebSocketSubscription,
  ControlPlaneWebSocketSubscriptionId,
  ControlPlaneWebSocketSubscribeStartAt,
  EventReadCursor
>>({
  latestSubscriptionStart: ControlPlaneWebSocketSubscribeOrigin.Latest,
  createError(fields) {
    return new GeneratedControlPlaneClientError({
      ...fields,
      details: fields.details,
    })
  },
  errorFields(error) {
    if (!(error instanceof GeneratedControlPlaneClientError)) return null
    return {
      code: error.code,
      message: error.message,
      requestId: error.requestId,
      retryable: error.retryable,
      details: error.details,
    }
  },
  matchesAuthSession(value): value is AuthSessionResponse {
    return matchesCanonicalSchema('AuthSessionResponse', value)
  },
  createHttpClient(options) {
    const client = createControlPlaneHttpClient({
      baseUrl: options.baseUrl,
      fetch: (input, init) => (
        Reflect.apply(options.fetch, undefined, [input, {
          method: init.method,
          headers: init.headers,
          body: init.body,
          credentials: 'include',
        }])
      ),
      maxNetworkRetries: options.maxNetworkRetries,
      waitBeforeRetry: options.waitBeforeRetry,
    })
    return {
      submitCommand(command) {
        return client.submitCommand(command)
      },
      submitQuery(query) {
        return client.submitQuery(query)
      },
    }
  },
  createWebSocketClient(options) {
    const onResetRequired = options.onResetRequired
    const socketOptions: ControlPlaneWebSocketClientOptions = {
      baseUrl: options.baseUrl,
      ...(options.createSocket === undefined ? {} : { createSocket: options.createSocket }),
      reconnectDelayMillis: options.reconnectDelayMillis,
      ...(options.onEventQueued === undefined ? {} : {
        onEventQueued: event => { options.onEventQueued?.(event) },
      }),
      onEvent: event => options.onEvent(event),
      ...(onResetRequired === undefined ? {} : {
        async onResetRequired(frame) {
          return onResetRequired(frame)
        },
      }),
      ...(options.onAuthorizationRevoked === undefined ? {} : {
        onAuthorizationRevoked: frame => options.onAuthorizationRevoked?.(frame),
      }),
      ...(options.onError === undefined ? {} : { onError: options.onError }),
    }
    const client = createControlPlaneWebSocketClient(socketOptions)
    return {
      get cursor() { return client.cursor },
      subscribe(subscriptionId, subscription, startAt) {
        client.subscribe(
          subscriptionId,
          subscription,
          startAt,
        )
      },
      resume() { client.resume() },
      reconnect() { client.reconnect() },
      close() { client.close() },
    }
  },
})

function createControlPlaneHttpClient(
  options: ControlPlaneHttpClientOptions = {},
): ControlPlaneHttpClient {
  const fetchImplementation = options.fetch ?? defaultFetch
  const maximumRetries = options.maxNetworkRetries ?? 0
  if (!Number.isSafeInteger(maximumRetries) || maximumRetries < 0 || maximumRetries > 5) {
    throw clientFailure('INVALID_CLIENT_OPTIONS', 'maxNetworkRetries must be between zero and five.')
  }
  const waitBeforeRetry = options.waitBeforeRetry ?? (async () => {})

  async function send(
    path: string,
    request: CommandRequest | QueryRequest,
  ): Promise<unknown> {
    let serialized: string
    try {
      serialized = JSON.stringify(request)
    } catch {
      throw clientFailure(
        'INVALID_CLIENT_REQUEST',
        'The Control Plane request could not be encoded.',
        request.requestId,
      )
    }
    const init: ControlPlaneHttpRequestInit = {
      method: 'POST',
      headers: {
        accept: 'application/json',
        'content-type': 'application/json',
      },
      body: serialized,
      credentials: 'same-origin',
    }
    let attempt = 0
    for (;;) {
      let response: ControlPlaneHttpResponse
      try {
        response = await fetchImplementation(endpoint(options.baseUrl, path), init)
      } catch (error) {
        if (error instanceof ControlPlaneClientError) throw error
        if (attempt >= maximumRetries) {
          throw clientFailure(
            'NETWORK_ERROR',
            'The Control Plane request did not reach the server.',
            request.requestId,
            true,
          )
        }
        attempt += 1
        try {
          await waitBeforeRetry(attempt)
        } catch {
          throw clientFailure(
            'NETWORK_ERROR',
            'The Control Plane request retry was interrupted.',
            request.requestId,
            true,
          )
        }
        continue
      }
      const parsed = await responseJson(response, request.requestId)
      if (!response.ok) throw parseErrorEnvelope(parsed, request.requestId)
      return parsed
    }
  }

  return {
    async submitCommand(command) {
      if (!matchesCanonicalSchema('CommandRequest', command)) throw clientFailure(
        'INVALID_CLIENT_REQUEST',
        'The command does not match its canonical discriminator.',
        clientRequestId(command),
      )
      return parseCommandResponse(
        await send(CONTROL_PLANE_COMMAND_PATH, command),
        command,
      )
    },
    async submitQuery(query) {
      if (!matchesCanonicalSchema('QueryRequest', query)) throw clientFailure(
        'INVALID_CLIENT_REQUEST',
        'The query does not match its canonical discriminator.',
        clientRequestId(query),
      )
      return parseQueryResponse(await send(CONTROL_PLANE_QUERY_PATH, query), query)
    },
  }
}

