function clarificationUpdateCommand(
  input: ClarificationSaveInput,
  actor: Actor,
  scope: RepositoryScope,
): DeliveryUpdateSpecCommand {
  return {
    schemaVersion: 'winwincode/v1',
    command: 'delivery.update_spec',
    actor,
    scope,
    requestId: input.requestId,
