pub fn delivery_update_spec(
        &mut self,
        command: &DeliveryUpdateSpecCommand,
    ) -> Result<DeliveryUpdateSpecCompletedResponse, DeliveryApplicationError> {
        let mapped = map_command(
            &command.actor,
            CommandName::DeliveryUpdateSpec,
            command.expected_revision.clone(),
            &command.payload,
            &command.request_id,
            &command.schema_version,
            &command.scope,
        )?;
        if let Some((receipt, delivery)) =
            self.delivery_replay(&mapped, &command.scope, &command.payload.delivery_id)?
        {
            return update_response(command, &receipt, &delivery);
        }
        ensure_catalog_membership(
            self.storage_ref()?,
            &command.scope,
            &command.payload.delivery_id,
        )?;
        let current = load_current_delivery(self.storage_ref()?, &command.payload.delivery_id)?;
        validate_spec_secret_safety(&command.payload.spec)?;
        let source_session_guard = validate_source_product_session(
            self.storage_ref()?,
            &command.actor,
            &command.scope,
            command.payload.spec.source_product_session_id.as_ref(),
        )?;
        let authority = self.resolve_specification_authority(&mapped, Some(&current))?;
        let facts = DeliveryCommandFacts::specification_from_trusted_adapter(
            &mapped,
            command.scope.clone(),
            specification_facts(authority, source_session_guard),
        )?;
        let receipt = self
            .commit_delivery_command(&mapped, &facts)
            .map_err(DeliveryApplicationError::Command)?;
        let delivery = load_delivery_revision(
            self.storage_ref()?,
            &command.payload.delivery_id,
            receipt.revision,
        )?;
        update_response(command, &receipt, &delivery)
    }

fn map_command<T: Serialize>(
    actor: &Actor,
    command: CommandName,
    expected_revision: Revision,
    payload: &T,
    request_id: &RequestId,
    schema_version: &SchemaVersion,
    scope: &RepositoryScope,
) -> Result<CommandEnvelope, DeliveryApplicationError> {
    if schema_version != &SchemaVersion::WinwincodeV1 {
        return Err(DeliveryApplicationError::InvalidRequest(
            "Delivery command schemaVersion is invalid".to_owned(),
        ));
    }
    let mapped = CommandEnvelope {
        actor: actor.clone(),
        command,
        expected_revision,
        payload: serde_json::to_value(payload).map_err(|error| {
            DeliveryApplicationError::InvalidRequest(format!(
                "Delivery command payload cannot be encoded: {error}"
            ))
        })?,
        request_id: request_id.clone(),
        schema_version: schema_version.clone(),
        scope: Scope::RepositoryScope(scope.clone()),
    };
    crate::command_receipt(&mapped)?;
    Ok(mapped)
}

fn resolve_specification_authority(
        &mut self,
        command: &CommandEnvelope,
        delivery: Option<&Delivery>,
    ) -> Result<DeliverySpecificationAuthority, DeliveryApplicationError> {
        let mut port = self.take_delivery_authority()?;
        let result = port.specification(DeliveryAuthorityRequest { command, delivery });
        self.delivery_authority = Some(port);
        result.map_err(authority_error)
    }

fn take_delivery_authority(
        &mut self,
    ) -> Result<Box<dyn DeliveryAuthorityPort>, DeliveryApplicationError> {
        self.delivery_authority.take().ok_or_else(|| {
            DeliveryApplicationError::TrustedFactsUnavailable(
                "Delivery authority port is not installed".to_owned(),
            )
        })
    }

pub fn install_local_delivery_adapters(
        &mut self,
        config: LocalDeliveryAdapterConfig,
    ) -> Result<(), LocalDeliveryAdapterError> {
        if self.delivery_authority.is_some()
            || self.delivery_dispatcher.is_some()
            || self.strongflow_sources.is_some()
            || self.git_source_resolver.is_some()
            || self.git_repository_root.is_some()
        {
            return Err(LocalDeliveryAdapterError::new(
                "Delivery production adapters are already installed",
            ));
        }
        let data_directory = self
            .local_database_path
            .as_deref()
            .and_then(Path::parent)
            .ok_or_else(|| {
                LocalDeliveryAdapterError::new(
                    "Delivery production adapters require local Control Plane storage",
                )
            })?;
        let repository_scope = config.repository_scope.clone();
        let authority = LocalDeliveryAuthority::open(config, data_directory)?;
        // Candidate source reconstruction and Git retention must share the
        // resolver's one canonical parent root.  Keep the root until every
        // adapter has opened successfully, then install both authorities as
        // one composition step below.
        let repository_source_root = authority.repository_source_root.clone();
        let dispatcher = LocalExecutionJobDispatcher::open(data_directory, repository_scope)?;
        let source_resolver = LocalGitSourceResolver::open_artifact_cache(&repository_source_root)
            .map_err(|error| {
                LocalDeliveryAdapterError::new(format!(
                    "failed to open the local Git candidate resolver: {error}"
                ))
            })?;
        self.install_strongflow_projection_sources(
            crate::strongflow_projection::production_sources(),
        )
        .map_err(|error| {
            LocalDeliveryAdapterError::new(format!(
                "failed to install StrongFlow projection sources: {error}"
            ))
        })?;
        self.delivery_authority = Some(Box::new(authority));
        self.delivery_dispatcher = Some(Box::new(dispatcher));
        self.git_repository_root = Some(repository_source_root);
        self.git_source_resolver = Some(Box::new(source_resolver));
        Ok(())
    }

